// Drop-charge index — record JAH-GGN-WIRELESSCHARGER-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"watts": 15, "coils": 1, "price_usd": 25};
var value = (m.watts*m.coils/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GGN-WIRELESSCHARGER-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GGN-WIRELESSCHARGER-000001|' + value.toFixed(2) + ' charge index');

